// Indirect calls through the generated function table, and the special
// registers lifted code may read or write. Runtime code: no std::format.
#include <algorithm>
#include <chrono>

#include "guest.hpp"

namespace qilin::rt {

// Generated by `qilin lift` (table.cpp): every function, sorted by address.
extern const FnEntry g_functions[];
extern const size_t g_function_count;

void call(Context& c, uint32_t target, uint32_t from) {
    const FnEntry* end = g_functions + g_function_count;
    const FnEntry* it = std::lower_bound(g_functions, end, target,
                                         [](const FnEntry& e, uint32_t a) { return e.addr < a; });
    if (it == end || it->addr != target) bad_jump(from, target);
    it->fn(c);
}

namespace {
constexpr bool plain_spr(unsigned spr) {
    return (spr >= 912 && spr <= 919)  // GQR0-7: paired-single quantisation
           || spr == 920               // HID2: paired-single and locked-cache enables
           || (spr >= 272 && spr <= 275);  // SPRG0-3: scratch
}
}  // namespace

uint32_t mfspr(Context& c, unsigned spr, uint32_t pc) {
    if (!plain_spr(spr)) throw Stop{Stop::Unsupported, pc, spr};
    return c.spr[spr];
}

void mtspr(Context& c, unsigned spr, uint32_t v, uint32_t pc) {
    if (!plain_spr(spr)) throw Stop{Stop::Unsupported, pc, spr};
    c.spr[spr] = v;
}

// The time base runs at a quarter of the bus clock: 243 MHz / 4 on the Wii.
uint64_t time_base() {
#ifdef QILIN_DETERMINISTIC_TIME
    return kTimeStart + g_time_reads++ * kTimeStep;
#else
    using namespace std::chrono;
    const auto ns = static_cast<uint64_t>(duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count());
    return ns / kNsPerSecond * kTimeBaseHz + ns % kNsPerSecond * kTimeBaseHz / kNsPerSecond;  // no overflow for centuries
#endif
}

uint32_t mftb(Context&, unsigned tbr) {
    const uint64_t ticks = time_base();
    return tbr == 269 ? static_cast<uint32_t>(ticks >> 32) : static_cast<uint32_t>(ticks);
}

void syscall(Context&, uint32_t pc) { throw Stop{Stop::Unsupported, pc, 0}; }

}  // namespace qilin::rt
